DO $pre$ BEGIN
 IF (SELECT count(*) FROM _u)<>19 OR (SELECT count(DISTINCT code) FROM _u)<>19 OR (SELECT sum(ects) FROM _u)<>120
 OR EXISTS(SELECT 1 FROM _u WHERE option_group IS NOT NULL OR semester<>(year-1)*2+local_semester OR jsonb_array_length(placements)<>1)
 OR (SELECT count(*) FROM (SELECT semester FROM _u GROUP BY semester HAVING sum(ects)=30) s)<>4
 OR (SELECT count(*) FROM _p)<>28 OR (SELECT count(*) FROM _pl)<>28
 OR EXISTS(SELECT 1 FROM _pl WHERE confidence NOT IN('alta','média'))
 THEN RAISE EXCEPTION 'Unexpected Desenho e Modelação Digital manifest counts or ECTS (expected 19 units, 4 x 30 = 120 ECTS)'; END IF;
 IF EXISTS(SELECT 1 FROM _p WHERE id !~ '^PL[A-Za-z0-9_-]{10,60}$' OR url<>'https://www.youtube.com/playlist?list='||id
 OR length(trim(title))<3 OR videos<4 OR language NOT IN('pt-PT','pt-BR','pt','en'))
 OR EXISTS(SELECT 1 FROM _pl t LEFT JOIN _p p ON p.id=t.playlist_id LEFT JOIN _u u ON u.code=t.code WHERE p.id IS NULL OR u.code IS NULL)
 THEN RAISE EXCEPTION 'Invalid playlist metadata or link'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.courses WHERE (code='CTESP-DMD' OR slug='ctesp-desenho-modelacao-digital' OR (external_source='ualg_official' AND external_id='1843'))
 AND id<>md5('facodi:ualg:1843:course:record')::uuid)
 THEN RAISE EXCEPTION 'Another course already uses CTESP-DMD, ctesp-desenho-modelacao-digital or UAlg 1843; reconcile manually'; END IF;
END $pre$;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,objectives,keywords,tags,language,status,published,source_type,source_url,source_id,metadata)
VALUES(md5('facodi:ualg:1843:course')::uuid,'course','CTeSP em Desenho e Modelação Digital','facodi-course-ctesp-desenho-modelacao-digital',
 'Curso Técnico Superior Profissional da Universidade do Algarve, no Instituto Superior de Engenharia, em Faro, com 120 ECTS em quatro semestres. Desenho técnico e CAD, BIM na arquitetura, nas estruturas e nas redes, topografia, digitalização 3D, SIG, medições e animação, com três projetos e estágio de 30 ECTS.','[]'::jsonb,ARRAY['Desenho e Modelação Digital','CTeSP','BIM','CAD','Topografia','SIG'],ARRAY['CTeSP em Desenho e Modelação Digital'],
 'pt','active',true,'import','https://www.ualg.pt/curso/1843','ualg:ctesp:1843:course',
 jsonb_build_object('university_course_code','1843','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1843/plano',
 'campus','Faro','mode','presencial','academic_institutions',jsonb_build_array('Instituto Superior de Engenharia'),
 'source_quality','ualg_official_programme','curation_batch','facodi_ualg_1843_ctesp_desenho_modelacao_digital_20261118'))
ON CONFLICT DO NOTHING;

INSERT INTO facodi.courses(id,learning_object_id,code,external_source,external_id,slug,title,normalized_title,summary,description_html,
 degree_type,language,school,source_url,plan_url,status,published,metadata,institution,ects_total,duration_semesters)
VALUES(md5('facodi:ualg:1843:course:record')::uuid,md5('facodi:ualg:1843:course')::uuid,'CTESP-DMD','ualg_official','1843','ctesp-desenho-modelacao-digital',
 'CTeSP em Desenho e Modelação Digital','Desenho e Modelação Digital','Curso Técnico Superior Profissional da Universidade do Algarve, no Instituto Superior de Engenharia, em Faro, com 120 ECTS em quatro semestres. Desenho técnico e CAD, BIM na arquitetura, nas estruturas e nas redes, topografia, digitalização 3D, SIG, medições e animação, com três projetos e estágio de 30 ECTS.','<h2>Apresentação</h2><p>O CTeSP em Desenho e Modelação Digital forma técnicos para participar na produção de projetos de arquitetura e de especialidades de engenharia, na construção civil e obras públicas, como desenhadores de CAD e modeladores BIM, com competências em técnicas de apresentação, simulação e animação de projeto.</p><h2>Plano de estudos</h2><p>Nos três primeiros semestres há cinco UCs de 4 ECTS e um projeto de 10 ECTS por semestre; o quarto é o estágio de 30 ECTS. O 1.º semestre trata desenho técnico, CAD, edifícios, matemática e topografia; o 2.º, BIM na arquitetura, digitalização e modelação 3D, infraestruturas urbanas, programação e inventariação; o 3.º, BIM nas estruturas e nas redes, medições e orçamentação, SIG, animação digital e computação visual. Os Projetos I, II e III juntam as UCs de cada semestre num trabalho prático.</p><h2>Na FACODI</h2><p>Cada unidade curricular tem playlists abertas do YouTube escolhidas a partir do programa da ficha oficial da UC.</p>',
 'CTeSP','pt','Instituto Superior de Engenharia','https://www.ualg.pt/curso/1843','https://www.ualg.pt/curso/1843/plano','active',true,
 jsonb_build_object('level','CTeSP (nível 5)','campus','Faro','official_course_id','1843','official_academic_year','2026/27',
 'official_plan_url','https://www.ualg.pt/curso/1843/plano','official_source','https://www.ualg.pt/curso/1843/plano','official_program_verified',true,'official_ects_total',120,
 'official_unit_count',19,'mandatory_unit_count',19,'official_semester_count',4,'curriculum_is_ctesp_not_licenciatura',true,
 'curriculum_contains_elective_alternatives',false,
 'source_quality','ualg_official_programme','curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1843_ctesp_desenho_modelacao_digital_20261118'),
 'Universidade do Algarve',120,4)
ON CONFLICT DO NOTHING;

