 u.topics,ARRAY[u.title],'pt','active',true,'import','https://www.ualg.pt/curso/1843/plano','ualg:ctesp:1843:uc:'||u.code,
 jsonb_build_object('university_course_code','1843','unit_code',u.code,'official_academic_year','2026/27',
 'official_fuc_url',u.fuc_url,'detailed_fuc_checked',u.fuc_url IS NOT NULL,'study_topics',to_jsonb(u.topics),'curation_batch','facodi_ualg_1843_ctesp_desenho_modelacao_digital_20261118')
