INSERT INTO facodi.curricular_units(id,learning_object_id,course_id,code,external_source,external_id,slug,title,normalized_title,summary,
 description_html,year,semester,ects,position,language,source_url,plan_url,status,published,metadata)
SELECT md5('facodi:ualg:1843:uc:record:'||u.code)::uuid,md5('facodi:ualg:1843:uc:'||u.code)::uuid,md5('facodi:ualg:1843:course:record')::uuid,
 u.code,'ualg_official','1843:'||u.code,
 CASE WHEN EXISTS(SELECT 1 FROM facodi.curricular_units o WHERE o.slug=u.code AND o.course_id<>md5('facodi:ualg:1843:course:record')::uuid)
 THEN 'ctesp-desenho-modelacao-digital-uc-'||u.code ELSE u.code END,
 u.title,u.title,u.summary,'<p>'||u.summary||'</p><p><strong>Temas:</strong> '||array_to_string(u.topics,'; ')||'.</p>',
 u.year,u.semester,u.ects,u.position,'pt','https://www.ualg.pt/curso/1843/plano','https://www.ualg.pt/curso/1843/plano','active',true,
 jsonb_build_object('course_code','CTESP-DMD','official_course_id','1843','official_unit_code',u.code,'academic_year','2026/27',
 'official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1843/plano','official_fuc_url',u.fuc_url,'detailed_fuc_checked',u.fuc_url IS NOT NULL,
 'official_code_checked',true,'official_ects_checked',true,'official_semester_checked',true,'local_semester',u.local_semester,
 'offered_in_both_semesters',u.offered_both_terms,'is_elective_option',u.option_group IS NOT NULL,'official_option_group',u.option_group,
 'curriculum_placements',u.placements,'study_topics',to_jsonb(u.topics),'source_quality','ualg_official_structure',
 'curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1843_ctesp_desenho_modelacao_digital_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:ualg:1843:course-uc-link:'||u.code)::uuid,md5('facodi:ualg:1843:course')::uuid,md5('facodi:ualg:1843:uc:'||u.code)::uuid,
 'contains',u.position,'structured_catalog_import',
 jsonb_build_object('relation_origin','ualg_1843_official_2026_27_plan','official_code',u.code,'official_ects',u.ects,'curation_batch','facodi_ualg_1843_ctesp_desenho_modelacao_digital_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

INSERT INTO facodi.external_sources(id,learning_object_id,source_type,external_id,source_url,title,metadata)
VALUES(md5('facodi:ualg:1843:source:course')::uuid,md5('facodi:ualg:1843:course')::uuid,'website','ualg:1843:course',
 'https://www.ualg.pt/curso/1843','CTeSP em Desenho e Modelação Digital',
 jsonb_build_object('publisher','Universidade do Algarve','academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1843/plano'))
ON CONFLICT DO NOTHING;

-- Playlists: reutiliza um registo existente com o mesmo ID do YouTube; senão cria um novo.
INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,language,status,published,source_type,source_url,source_id,tags,metadata)
SELECT md5('facodi:ualg:1843:playlist:'||p.id)::uuid,'playlist',p.title,'facodi-uc-playlist-'||p.id,p.description,p.language,
 'active',true,'youtube',p.url,p.id,p.tags,
 jsonb_build_object('source_channel',p.channel,'source_channel_url',p.channel_url,'youtube_playlist_id',p.id,
 'video_count_at_verification',p.videos,'playlist_title_checked',true,'playlist_owner_verified',true,
 'owner_verification_method','youtube_oembed','items_channel_checked',true,'playlist_membership_verified',false,
 'items_automatically_imported',false,'verified_on','2026-11-18','curation_batch','facodi_ualg_1843_ctesp_desenho_modelacao_digital_20261118')
FROM _p p
WHERE NOT EXISTS(SELECT 1 FROM facodi.learning_objects lo WHERE lo.object_type='playlist' AND lo.source_type='youtube' AND lo.source_id=p.id)
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:ualg:1843:uc-playlist:'||x.code||':'||x.playlist_id)::uuid,md5('facodi:ualg:1843:uc:'||x.code)::uuid,lo.id,
 'contains',91000+x.ord,'structured_catalog_import',
 jsonb_build_object('review_status','approved','review_scope','uc_programme_topic_match','match_confidence',x.confidence,
 'content_level',x.level,'match_rationale',x.match,'curation_batch','facodi_ualg_1843_ctesp_desenho_modelacao_digital_20261118','playlist_owner_verified',true,'members_verified',false)
FROM _pl x
JOIN LATERAL (SELECT id FROM facodi.learning_objects WHERE object_type='playlist' AND source_type='youtube' AND source_id=x.playlist_id
 ORDER BY (id=md5('facodi:ualg:1843:playlist:'||x.playlist_id)::uuid) DESC, id LIMIT 1) lo ON true
ON CONFLICT DO NOTHING;

DO $post$ DECLARE units integer; links integer; BEGIN
 SELECT count(*) INTO units FROM facodi.curricular_units
 WHERE course_id=md5('facodi:ualg:1843:course:record')::uuid AND published AND status='active' AND learning_object_id IS NOT NULL
 AND jsonb_array_length(metadata->'curriculum_placements')>0;
 SELECT count(*) INTO links FROM _pl x JOIN facodi.learning_object_relations r ON r.parent_object_id=md5('facodi:ualg:1843:uc:'||x.code)::uuid
 AND r.relation_type='contains' JOIN facodi.learning_objects lo ON lo.id=r.child_object_id AND lo.object_type='playlist' AND lo.source_id=x.playlist_id;
 IF NOT EXISTS(SELECT 1 FROM facodi.courses WHERE code='CTESP-DMD' AND published AND status='active' AND ects_total=120 AND duration_semesters=4)
 OR units<>19 OR links<>28
 THEN RAISE EXCEPTION 'Desenho e Modelação Digital import not complete: units %, playlist links %',units,links; END IF;
END $post$;

COMMIT;
